\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── IMF Custom Color Theme ──
\definecolor{primary}{HTML}{002244}
\definecolor{secondary}{HTML}{1E4D7B}
\definecolor{accent}{HTML}{D97706}
\definecolor{bgposter}{HTML}{F0F2F5}
\definecolor{navybg}{HTML}{EEF1F7}
\definecolor{amberbg}{HTML}{FFF8F0}
\definecolor{darkbg}{HTML}{F2F3F7}
\definecolor{navytitlebg}{HTML}{E2E7F0}
\definecolor{ambertitlebg}{HTML}{FDEBD0}
\definecolor{darktitlebg}{HTML}{E4E6EC}
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{FEE8E0}
\definecolor{warnbg}{HTML}{FEF3E8}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=navytitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=ambertitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

% ── Table styling ──
\renewcommand{\arraystretch}{1.5}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════
% TITLE BAR (span=3, rows 0-4)
% ═══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{68}{82}\selectfont\bfseries Global Economy in the Shadow of War}\\[10pt]
  {\fontsize{36}{44}\selectfont IMF World Economic Outlook Trends 2024--2026}\\[14pt]
  {\fontsize{28}{34}\selectfont\color{white!70} IMF--World Bank Annual Meetings Research Symposium \quad$\bullet$\quad
   Eight WEO Editions Reviewed \quad$\bullet$\quad July 2024 -- April 2026}
}

% ═══════════════════════════════════════════════
% STAT BANNER (span=3, rows 4-6)
% ═══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!white, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!40}{navybg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 3.0\%}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Global Growth 2025}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray!70} WEO Jul 2025 Update}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!40}{navybg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 3.3\%}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Global Growth 2026}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray!70} WEO Jan 2026 Update}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!50}{warnbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{42}{52}\selectfont\bfseries\color{accent} Tilted $\downarrow$}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textgray} Risk Balance}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textgray!70} All 8 WEO editions}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════
% ROW A: rows 6-11 — Growth Trajectory + Risks + Inflation
% ═══════════════════════════════════════════════

% COL 1: Global Growth Projections
\posterbox[navycard, title={Global Growth: A Narrow Band}
]{name=growth, column=1, between=row6 and row11}{
  \vspace{2mm}
  {\fontsize{26}{33}\selectfont\color{textgray}Growth stuck at 3.0--3.3\% --- well below the pre-pandemic average of $\sim$3.8\%.\par}
  \vspace{4mm}
  {\fontsize{22}{28}\selectfont
  \renewcommand{\arraystretch}{1.45}
  \begin{tabular}{p{0.40\linewidth}cccc}
    \rowcolor{primary!20}
    \bfseries WEO Edition & \bfseries\textquotesingle24 & \bfseries\textquotesingle25 & \bfseries\textquotesingle26 & \bfseries\textquotesingle27 \\
    Jul 2024: Sticky Spot       & 3.2\% & 3.3\%  & ---   & --- \\
    Oct 2024: Policy Pivot      & 3.2\% & 3.3\%  & ---   & --- \\
    Jan 2025: Divergent         & ---   & 3.3\%  & 3.3\% & --- \\
    Apr 2025: Critical Juncture & ---   & $\downarrow$ & $\downarrow$ & --- \\
    Jul 2025: Tenuous Resilience& ---   & \textbf{3.0\%} & 3.1\% & --- \\
    Oct 2025: Flux              & ---   & $\downarrow$ & $\downarrow$ & --- \\
    Jan 2026: Steady            & ---   & 3.3\%  & 3.2\% & 3.2\% \\
    Apr 2026: Shadow of War     & ---   & $\downarrow$ & $\downarrow$ & --- \\
  \end{tabular}
  }
  \vspace{2mm}
  \begin{center}
    {\fontsize{22}{28}\selectfont\color{accent}$\downarrow$ = slowing / renewed pressure}
  \end{center}
}

% COL 2: Dominant Downside Risks
\posterbox[ambercard, title={Dominant Downside Risks}
]{name=risks, column=2, between=row6 and row11}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Trade policy escalation} --- Tariff increases and retaliatory measures, with front-loaded activity masking near-term damage
    \item \textbf{Geopolitical tensions} --- Middle East conflicts, broader security concerns, and ongoing war effects
    \item \textbf{Technology re-evaluation} --- Risk that elevated AI and tech investment expectations face a correction
    \item \textbf{Persistent services inflation} --- US inflation projected to return to target more gradually than peers
  \end{itemize}
  \vspace{2mm}
  \colorbox{accent!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{28}{36}\selectfont\color{accent}\bfseries
    Risk balance: consistently tilted to the downside across all eight editions
  }}
}

% COL 3: Inflation Outlook & Monetary Policy
\posterbox[navycard, title={Inflation \& Monetary Policy}
]{name=inflation, column=3, between=row6 and row11}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Global headline inflation on a declining trajectory through 2026, enabling the ``policy pivot''
    \item US inflation remains above target longer than peer economies --- services inflation especially sticky
    \item Renewed inflationary pressures emerged by April 2026, linked to defense spending and supply disruptions
    \item Central banks began easing from late 2024, but the path is uneven across advanced economies
  \end{itemize}
  \vspace{2mm}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{26}{34}\selectfont
    \textbf{Key tension:} Disinflation progress vs.\ renewed price pressures from fiscal expansion
  }}
}

% ═══════════════════════════════════════════════
% ROW B: rows 11-16 — Policy Evolution + Themes + US Exception
% ═══════════════════════════════════════════════

% COL 1: Evolving Policy Priorities
\posterbox[darkcard, title={Evolving Policy Priorities}
]{name=policy, column=1, between=row11 and row16}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=5pt]
    \item \textbf{Mid-2024} $\rightarrow$ Manage disinflation; begin monetary easing carefully
    \item \textbf{Late 2024} $\rightarrow$ Pivot monetary policy; ensure fiscal sustainability
    \item \textbf{Early 2025} $\rightarrow$ Rebuild fiscal buffers; address demographic and gender gaps
    \item \textbf{Mid-2025} $\rightarrow$ Restore confidence amid tariff uncertainty
    \item \textbf{Late 2025} $\rightarrow$ Strengthen policy frameworks; cautious industrial policy
    \item \textbf{Early 2026} $\rightarrow$ Agile policy; defense-spending trade-offs; lay recovery foundations
  \end{itemize}
  \vspace{2mm}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{24}{30}\selectfont
    Shift: fiscal buffers $\to$ structural reforms $\to$ defense-spending trade-offs
  }}
}

% COL 2: Special Analytical Themes
\posterbox[navycard, title={Special Analytical Themes}
]{name=themes, column=2, between=row11 and row16}{
  \fontsize{28}{36}\selectfont
  Each WEO edition features deep-dive analytical chapters. Notable themes across the review period:
  \vspace{4mm}
  \begin{itemize}[itemsep=8pt]
    \item Role of monetary policy in global disinflation
    \item Social acceptability of structural reforms
    \item Effectiveness and fiscal cost of industrial policy
    \item Policies for aging populations and gender disparities
    \item Migrant skill alignment and labor market integration
  \end{itemize}
  \vspace{2mm}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{26}{34}\selectfont
    Broadening lens: beyond macroeconomic stabilization toward inclusive, sustainable growth
  }}
}

% COL 3: US Inflation Exception
\posterbox[ambercard, title={US Inflation: The Outlier}
]{name=usinf, column=3, between=row11 and row16}{
  \fontsize{28}{36}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item US inflation projected to stay above target longer than other advanced economies
    \item Services inflation has been particularly sticky, slowing the overall disinflation process
    \item This divergence complicates global monetary policy coordination
  \end{itemize}
  \vspace{4mm}
  \colorbox{accent!15}{\parbox{0.92\linewidth}{%
    \centering\fontsize{26}{34}\selectfont
    \textbf{Implication:} The Fed's ``higher for longer'' stance constrains EM easing cycles and strengthens USD
  }}
  \vspace{4mm}
  {\fontsize{26}{34}\selectfont
  \textbf{Renewed pressure (2026):} Defense spending and supply disruptions are creating fresh inflationary headwinds, complicating the policy pivot narrative.
  }
}

% ═══════════════════════════════════════════════
% ROW C: rows 16-20 — Takeaways + Methodology + References
% ═══════════════════════════════════════════════

% COL 1: Key Takeaways
\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row16 and bottom}{
  \fontsize{26}{34}\selectfont\color{textdark}
  \begin{enumerate}[itemsep=8pt, label={\color{white}\bfseries\arabic*.}]
    \item \textbf{Persistent mediocrity:} Global growth oscillates in a narrow 3.0--3.3\% band, failing to recover to the pre-pandemic 3.8\% trend
    \item \textbf{Downside dominance:} Across every WEO edition, risk assessments are tilted to the downside --- trade policy, geopolitics, and sticky inflation
    \item \textbf{Policy pivot under strain:} The shift from fiscal buffers to defense-spending trade-offs reflects a world with less policy space and more demands
  \end{enumerate}
}

% COL 2: About This Analysis
\posterbox[darkcard, title={About This Analysis}
]{name=about, column=2, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{Source:} IMF World Economic Outlook reports, semi-annual and interim updates
    \item \textbf{Scope:} Eight editions spanning July 2024 through April 2026
    \item \textbf{Focus:} Global growth forecasts, risk assessments, inflation dynamics, and evolving policy guidance
  \end{itemize}
  \vspace{4mm}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{24}{32}\selectfont
    All data sourced from published IMF WEO documents. Arrows ($\downarrow$) indicate directional assessments where precise figures were not provided.
  }}
}

% COL 3: References
\posterbox[navycard, title={Key WEO Editions Reviewed}
]{name=references, column=3, between=row16 and bottom}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=5pt]
    \item IMF (Jul 2024). \textit{Sticky Spot Update}. WEO Update.
    \item IMF (Oct 2024). \textit{Policy Pivot, Rising Threats}. WEO.
    \item IMF (Jan 2025). \textit{Divergent and Uncertain}. WEO Update.
    \item IMF (Apr 2025). \textit{Critical Juncture}. WEO.
    \item IMF (Jul 2025). \textit{Tenuous Resilience}. WEO Update.
    \item IMF (Oct 2025). \textit{Flux, Prospects Dim}. WEO.
    \item IMF (Jan 2026). \textit{Steady amid Divergent Forces}. WEO Update.
    \item IMF (Apr 2026). \textit{Shadow of War}. WEO.
  \end{itemize}
}

\end{tcbposter}
\end{document}

